export function defineWorkspaceShell() {
 if(typeof window==='undefined'||customElements.get('gp-workspace-shell'))return;
 defineBrand();defineAppMenu();definePeopleCard();
 customElements.define('gp-workspace-shell', class extends HTMLElement {
  _user=null;_projects=[];_projectId=null;_token='';
  static get observedAttributes(){return ['embedded','search-placeholder','create-label','active-page','search-value'];}
  set user(value){this._user=value;this.updateUser();}get user(){return this._user;}
  set projects(value){this._projects=Array.isArray(value)?value:[];this.updateProjects();}
  set projectId(value){this._projectId=value;this.updateProjects();}
  set token(value){this._token=value||'';this.updateUser();}
  attributeChangedCallback(){this.updateAttributes();}
  connectedCallback(){
   if(!this.shadowRoot)this.render();
   this.outside=event=>{if(!event.composedPath().includes(this))this.closePanels();};
   this.keyboard=event=>{if(event.key==='Escape')this.closePanels();if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();this.shadowRoot.querySelector('.header-search:not([hidden]) input')?.focus();}};
   document.addEventListener('click',this.outside);document.addEventListener('keydown',this.keyboard);
  }
  disconnectedCallback(){document.removeEventListener('click',this.outside);document.removeEventListener('keydown',this.keyboard);}
  emit(name,detail){this.dispatchEvent(new CustomEvent(name,{detail,bubbles:true,composed:true}));}
  render(){
   const current=this.getAttribute('current')||'chatly',app=appRegistry().find(a=>a.id===current),sharedChrome=this.getAttribute('header-layout')==='relay',inbox=current==='mail'&&this.getAttribute('mail-layout')==='inbox',groups=inbox?[['Mail',[['Inbox','inbox','inbox'],['Starred','starred','star'],['Snoozed','snoozed','clock'],['Important','important','important'],['Sent','sent','sent'],['Drafts','drafts','edit'],['Archive','archive','folder'],['All mail','all','inbox'],['Spam','spam','spam'],['Trash','trash','trash']]]]:navigation[current]||[];
   const root=this.attachShadow({mode:'open'});
   root.innerHTML=`<style>${style}${workspaceVisualStyles}${productBrandStyles}${cleanVisualStyles('workspace',current,{sharedChrome})}${borderlessVisualStyles('workspace')}${current==='mail'?mailVisualStyles:''}</style><div class="shell"><header class="header"><div class="brand-group"><button class="icon-button menu-button" aria-label="Toggle navigation" aria-expanded="true">${icon('menu')}</button><a class="brand" aria-label="${escape(app?.name)} home" href="${appUrl(current)}"><gp-brand app="${escape(current)}" name="${escape(app?.name)}"></gp-brand></a></div><div class="header-controls"><div class="project-control" hidden><button class="project-trigger" aria-label="Choose project or space" aria-haspopup="dialog" aria-expanded="false">${icon('folder')}<span class="project-copy"><small>PROJECT / SPACE</small><strong>Choose a project</strong></span>${icon('chevron')}</button><section class="panel project-panel" hidden aria-label="Projects"><label class="search">${icon('search')}<input type="search" placeholder="Search projects" aria-label="Search projects"></label><div class="project-list"></div></section></div><div class="header-search-wrap"><form class="search header-search" role="search">${icon('search')}<input type="search" aria-label="Search ${escape(app?.name)}" placeholder="Search"><kbd>⌘ K</kbd></form><slot name="search-suggestions"></slot></div></div><div class="header-actions"><div class="create-wrapper"><button class="create" data-create>${current==='mail'?`<img src="${appLogo('mail')}" alt="">`:icon('plus')}<span>Create</span></button><slot name="create-menu"></slot></div><button class="icon-button help-button" aria-label="About this workspace" aria-haspopup="dialog">${icon('help')}</button><gp-theme-toggle></gp-theme-toggle><gp-apps current="${escape(current)}" ${sharedChrome?'shared-chrome':''}></gp-apps><slot name="header-actions-extra"></slot><button class="icon-button notifications-button" aria-label="Notifications" aria-haspopup="dialog" aria-expanded="false">${icon('bell')}</button><button class="avatar account-button" aria-label="Your account" aria-haspopup="dialog" aria-expanded="false">G</button><a class="signin" href="${appUrl('identity')}" hidden>Sign in</a></div><section class="panel account-panel" hidden aria-label="Your account"><div class="account-person"><span class="avatar">G</span><div class="person-copy"><strong></strong><small></small></div></div><a class="panel-action profile-link" href="${appUrl('people')}" target="_blank" rel="noopener noreferrer">${icon('person')}Profile</a><a class="panel-action" href="${appUrl('identity')}">${icon('person')}Manage your account</a><button class="panel-action signout">${icon('release')}Sign out of all apps</button></section><section class="panel notifications-panel" hidden aria-label="Notifications"><div class="panel-head"><strong>Notifications</strong><button class="icon-button close-panel" aria-label="Close notifications">${icon('close')}</button></div><div class="notification-list"></div></section><section class="panel help-panel" hidden aria-label="About this workspace"><div class="panel-head"><strong>${escape(app?.name)}</strong><button class="icon-button close-panel" aria-label="Close help">${icon('close')}</button></div><p class="panel-message">${escape(app?.caption)}. Use the Apps menu to move between your connected workspace apps with the same account.</p><a class="panel-action" href="${appUrl('documents')}">${icon('doc')}Open your documents</a></section></header><slot name="search-suggestions"></slot><div class="body"><aside class="sidebar" aria-label="Main navigation"><nav class="nav-scroll">${current==='mail'?`<button class="nav-item nav-create" data-create><img src="${appLogo('mail')}" alt=""><span>Compose</span></button>`:''}${groups.map(([label,items],i)=>`<section class="nav-group"><button class="group-toggle" aria-expanded="true" aria-controls="group-${i}">${icon('chevron')}${label}</button><div class="group-items" id="group-${i}">${items.map(([title,page,symbol])=>`<button type="button" class="nav-item" data-page="${page}" title="${title}">${icon(symbol)}<span>${title}</span></button>`).join('')}</div></section>`).join('')}<slot name="navigation-extra"></slot></nav><button class="collapse" aria-label="Collapse navigation">${icon('back')}<span>Collapse navigation</span></button></aside><div class="nav-resize" role="separator" tabindex="0" aria-orientation="vertical" aria-label="Resize navigation" aria-valuemin="176" aria-valuemax="420"></div><section class="content"><main class="canvas"><slot></slot></main><footer class="footer"><span>© ${new Date().getFullYear()} Greatley Poshley Ltd.</span><span class="footer-links"><a href="${appUrl('documents')}">Documentation</a><a href="${appUrl('identity')}">Your account</a></span></footer></section></div></div>`;
   root.querySelectorAll('[data-page]').forEach(button=>button.onclick=()=>{root.querySelector('.shell').classList.remove('mobile-expanded');this.emit('gp-navigate',button.dataset.page);});
   root.querySelectorAll('[data-create]').forEach(button=>button.onclick=()=>this.emit('gp-create',null));
   root.querySelector('.header-search input').oninput=event=>this.emit('gp-search-input',event.target.value);
   root.querySelector('.header-search').onsubmit=event=>{event.preventDefault();this.emit('gp-search',root.querySelector('.header-search input').value);};
   root.querySelector('.account-button').onclick=()=>this.togglePanel('.account-panel');
   root.querySelector('.help-button').onclick=()=>this.togglePanel('.help-panel');
   root.querySelector('.notifications-button').onclick=()=>{this.togglePanel('.notifications-panel');if(!root.querySelector('.notifications-panel').hidden)this.notifications();};
   root.querySelectorAll('.close-panel').forEach(button=>button.onclick=()=>this.closePanels());
   root.querySelector('.signout').onclick=()=>{this.closePanels();this.emit('gp-signout',null);};
   root.querySelector('.project-trigger').onclick=()=>{this.togglePanel('.project-panel');root.querySelector('.project-panel input').focus();};
   root.querySelector('.project-panel input').oninput=()=>this.updateProjects();
   root.querySelectorAll('.group-toggle').forEach(button=>button.onclick=()=>{const expanded=button.getAttribute('aria-expanded')==='true';button.setAttribute('aria-expanded',String(!expanded));root.getElementById(button.getAttribute('aria-controls')).hidden=expanded;});
   const collapse=()=>{if(this.getAttribute('integrated-navigation')==='true'){this._integratedCollapsed=!this._integratedCollapsed;this.emit('gp-navigation-toggle',!this._integratedCollapsed);root.querySelector('.menu-button').setAttribute('aria-expanded',String(!this._integratedCollapsed));return;}const shell=root.querySelector('.shell');if(matchMedia('(max-width:800px)').matches){shell.classList.toggle('mobile-expanded');}else{shell.classList.toggle('collapsed');try{sessionStorage.setItem('gp.navigation.collapsed',String(shell.classList.contains('collapsed')));}catch{}}const expanded=matchMedia('(max-width:800px)').matches?shell.classList.contains('mobile-expanded'):!shell.classList.contains('collapsed');root.querySelector('.menu-button').setAttribute('aria-expanded',String(expanded));root.querySelector('.collapse').setAttribute('aria-label',expanded?'Collapse navigation':'Expand navigation');root.querySelector('.collapse span').textContent=expanded?'Collapse navigation':'Expand navigation';};
   root.querySelector('.menu-button').onclick=collapse;root.querySelector('.collapse').onclick=collapse;
   try{root.querySelector('.shell').classList.toggle('collapsed',sessionStorage.getItem('gp.navigation.collapsed')==='true');}catch{}
   const shell=root.querySelector('.shell'),handle=root.querySelector('.nav-resize'),defaultWidth=inbox?256:218,widthKey=inbox?'gp.mail.navigation.width':'gp.navigation.width';let width=defaultWidth,start=0,initial=0,resizing=false;
   const setWidth=value=>{width=Math.max(176,Math.min(420,Math.min(innerWidth*.45,value)));shell.style.setProperty('--navigation-width',width+'px');handle.setAttribute('aria-valuenow',String(Math.round(width)));};
   try{setWidth(Number(localStorage.getItem(widthKey))||defaultWidth);}catch{setWidth(defaultWidth);}
   const finish=()=>{resizing=false;shell.classList.remove('resizing');try{localStorage.setItem(widthKey,String(width));}catch{}};
   handle.onpointerdown=e=>{if(e.button!==0)return;e.preventDefault();resizing=true;start=e.clientX;initial=width;handle.setPointerCapture(e.pointerId);shell.classList.add('resizing');};handle.onpointermove=e=>{if(resizing)setWidth(initial+e.clientX-start);};handle.onpointerup=finish;handle.onpointercancel=finish;handle.onlostpointercapture=finish;handle.ondblclick=()=>{setWidth(defaultWidth);finish();};handle.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();setWidth(e.key==='Home'?176:e.key==='End'?420:width+(e.key==='ArrowLeft'?-12:12));finish();}};
   let favicon=document.querySelector('link[rel~="icon"]');if(!favicon){favicon=document.createElement('link');favicon.rel='icon';document.head.appendChild(favicon);}favicon.href=appLogo(current);favicon.type='image/svg+xml';
   root.querySelector('.shell').classList.toggle('identity',current==='identity');
   this.updateAttributes();this.updateUser();this.updateProjects();
  }
  updateAttributes(){const root=this.shadowRoot;if(!root)return;root.querySelector('.shell').classList.toggle('embedded',this.getAttribute('embedded')==='true');root.querySelector('.header-search input').placeholder=this.getAttribute('search-placeholder')||'Search your workspace';if(this.hasAttribute('search-value')){const input=root.querySelector('.header-search input'),value=this.getAttribute('search-value')||'';if(input.value!==value)input.value=value;}root.querySelector('.create span').textContent=this.getAttribute('create-label')||'Create';const active=this.getAttribute('active-page');root.querySelectorAll('[data-page]').forEach(button=>{const selected=button.dataset.page===active;button.classList.toggle('current',selected);if(selected)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');});}
  updateUser(){
   const root=this.shadowRoot;if(!root)return;
   const user=this._user,name=[user?.firstName??user?.first_name,user?.lastName??user?.last_name].filter(Boolean).join(' ')||user?.name||user?.email||'Your account';
   const userId=user?.id??user?.userId??user?.user_id??user?.userAccountId??user?.user_account_id;
   root.querySelector('.profile-link').href=appUrl('people',{view:'users',userId});
   const initials=name.split(/\s+/).slice(0,2).map(p=>p[0]).join('').toUpperCase();
   const avatarUrl=user?.image||user?.avatarUrl||user?.avatar_url||user?.profilePictureUrl||user?.profile_picture_url||user?.profileImageUrl||user?.profile_image_url||'';
   root.querySelectorAll('.account-button,.account-person .avatar').forEach(avatar=>{
    avatar.dataset.tone=String(Number(user?.id||0)%5);
    avatar.replaceChildren();
    if(avatarUrl){const image=document.createElement('img');image.src=avatarUrl;image.alt='';image.referrerPolicy='no-referrer';image.onerror=()=>{avatar.dataset.hasPhoto='false';image.remove();avatar.textContent=initials;};avatar.dataset.hasPhoto='true';avatar.append(image);}
    else{avatar.dataset.hasPhoto='false';avatar.textContent=initials;}
   });
   root.querySelector('.person-copy strong').textContent=name;root.querySelector('.person-copy small').textContent=user?.email||'';
   root.querySelector('.shell').classList.toggle('public',!user);root.querySelector('.sidebar').hidden=!user||this.getAttribute('current')==='identity';root.querySelector('.menu-button').hidden=!user||this.getAttribute('current')==='identity';root.querySelector('.notifications-button').hidden=!user||!this._token||this.hasAttribute('custom-notifications');root.querySelector('.account-button').hidden=!user;root.querySelector('.signin').hidden=!!user||this.getAttribute('current')==='identity';root.querySelector('.header-search').hidden=!user||this.getAttribute('current')==='identity';root.querySelectorAll('[data-create]').forEach(button=>button.hidden=!user||this.getAttribute('current')==='identity');if(!user)this.closePanels();this.updateProjects();
  }
  updateProjects(){const root=this.shadowRoot;if(!root)return;const control=root.querySelector('.project-control');control.hidden=!['documents','instru','support','professy'].includes(this.getAttribute('current'))||!this._user;root.querySelector('.project-copy strong').textContent=this._projects.find(p=>Number(p.id)===Number(this._projectId))?.name||'Choose a project';const query=root.querySelector('.project-panel input').value.toLowerCase(),list=root.querySelector('.project-list');list.replaceChildren();for(const project of this._projects.filter(p=>String(p.name).toLowerCase().includes(query))){const button=document.createElement('button');button.type='button';button.className='project-row'+(Number(project.id)===Number(this._projectId)?' selected':'');button.innerHTML=`<span class="avatar" data-tone="${Number(project.id)%5}">${escape(String(project.name).split(/\s+/).slice(0,2).map(p=>p[0]).join(''))}</span><span>${escape(project.name)}</span>`;button.onclick=()=>{this.closePanels();this.emit('gp-project-change',Number(project.id));};list.append(button);}if(!list.children.length){const note=document.createElement('p');note.className='panel-message';note.textContent='No projects found.';list.append(note);}root.querySelector('gp-apps').setAttribute('project-id',this._projectId??'');}
  closePanels(){const root=this.shadowRoot;if(!root)return;root.querySelectorAll('.panel').forEach(panel=>panel.hidden=true);root.querySelectorAll('.account-button,.notifications-button,.project-trigger').forEach(button=>button.setAttribute('aria-expanded','false'));}
  togglePanel(selector){const panel=this.shadowRoot.querySelector(selector),open=panel.hidden;this.closePanels();panel.hidden=!open;const trigger={'.account-panel':'.account-button','.notifications-panel':'.notifications-button','.project-panel':'.project-trigger'}[selector];if(trigger)this.shadowRoot.querySelector(trigger).setAttribute('aria-expanded',String(open));}
  async notifications(){const list=this.shadowRoot.querySelector('.notification-list');list.innerHTML='<p class="panel-message">Loading notifications…</p>';try{const response=await fetch(`${location.protocol}//${location.hostname}:8080/api/notifications`,{headers:{Authorization:'Bearer '+this._token}});if(!response.ok){const error=new Error();error.status=response.status;throw error;}const data=await response.json();list.replaceChildren();for(const row of data.items||[]){const target=row.ticket_type==='MAIL'?'mail':row.ticket_type==='CHAT'?'chatly':row.ticket_type==='CALENDAR'?'calendar':'professy',link=document.createElement('a');link.className='notice';link.href=appUrl(target,target==='mail'?{messageId:row.ticket_id}:target==='chatly'?{conversation:row.ticket_id}:target==='calendar'?{eventId:row.ticket_id}:row.ticket_type==='TEST_CASE'?{menu:'test-cases',projectId:row.project_id,caseId:row.ticket_id}:{menu:'kanban-board',projectId:row.project_id,openId:row.ticket_id,openType:row.ticket_type});link.innerHTML=`<strong>${escape(row.title||'Workspace update')}</strong><p>${escape(row.body||row.summary)}</p><time>${escape(row.created_at?new Date(row.created_at).toLocaleString():'')}</time>`;list.append(link);}if(!list.children.length)list.innerHTML='<p class="panel-message">You’re up to date.</p>';}catch(error){list.replaceChildren();const message=document.createElement('p');message.className='panel-message';message.textContent=error.status===401?'Your sign-in expired. Reopen your account to sign in.':'The notification service is unavailable. Your messages and work are still saved.';const retry=document.createElement('button');retry.className='panel-action';retry.type='button';retry.textContent='Retry notifications';retry.onclick=()=>this.notifications();list.append(message,retry);}}
 });
}
